"""Independent pair-graph distance matrices and partial-word replay controls."""

ORIGINAL = 'impl PartialDynamics {\n    fn original_distinguish(\n        &self,\n        left: usize,\n        right: usize,\n        max_pairs: usize,\n    ) -> Result<Option<DistinguishingWord>, ContinuationError> {\n        if left >= self.reports.len() || right >= self.reports.len() {\n            return Err(ContinuationError::OutsideCarrier);\n        }\n        if max_pairs == 0 {\n            return Err(ContinuationError::WorkLimit);\n        }\n        let mut paths = BTreeMap::from([((left, right), Vec::new())]);\n        let mut queue = VecDeque::from([(left, right)]);\n        while let Some((l, r)) = queue.pop_front() {\n            let word = paths[&(l, r)].clone();\n            if self.machine.reports()[l] != self.machine.reports()[r] {\n                return Ok(Some(DistinguishingWord {\n                    left,\n                    right,\n                    word,\n                    left_answer: self.reports.get(l).copied(),\n                    right_answer: self.reports.get(r).copied(),\n                }));\n            }\n            for a in 0..self.machine.input_count() {\n                let pair = (\n                    self.machine.transitions()[l][a],\n                    self.machine.transitions()[r][a],\n                );\n                if !paths.contains_key(&pair) {\n                    if paths.len() >= max_pairs {\n                        return Err(ContinuationError::WorkLimit);\n                    }\n                    let mut next = word.clone();\n                    next.push(a);\n                    paths.insert(pair, next);\n                    queue.push_back(pair);\n                }\n            }\n        }\n        Ok(None)\n    }\n}\n'

TESTS = r'''
fn partial_run(p:&PartialDynamics,start:usize,word:&[usize])->Option<usize>{let mut state=Some(start);for &a in word{state=match state{Some(s)=>p.transitions[s][a],None=>None};}state}
fn observe(p:&PartialDynamics,state:usize)->Option<usize>{p.reports.get(state).copied()}
fn target(p:&PartialDynamics,state:usize,a:usize)->usize{p.transitions.get(state).and_then(|r|r[a]).unwrap_or(p.reports.len())}
fn distances(p:&PartialDynamics)->Vec<Option<usize>>{
 let n=p.reports.len()+1;let mut d:Vec<_>=(0..n*n).map(|v|(observe(p,v/n)!=observe(p,v%n)).then_some(0usize)).collect();
 // Independent synchronous Bellman relaxation on the entire product graph.
 for _ in 0..n*n{let old=d.clone();for v in 0..n*n{let mut best=old[v];for a in 0..p.machine.input_count(){let next=target(p,v/n,a)*n+target(p,v%n,a);if let Some(k)=old[next]{let k=k+1;if best.is_none_or(|b|k<b){best=Some(k);}}}d[v]=best;}if d==old{break;}}
 d
}
fn expected_word(p:&PartialDynamics,left:usize,right:usize,d:&[Option<usize>])->Option<DistinguishingWord>{let n=p.reports.len()+1;let mut pair=(left,right);let mut remaining=d[left*n+right]?;let mut word=Vec::new();while remaining>0{let a=(0..p.machine.input_count()).find(|&a|{let next=target(p,pair.0,a)*n+target(p,pair.1,a);d[next]==Some(remaining-1)}).unwrap();word.push(a);pair=(target(p,pair.0,a),target(p,pair.1,a));remaining-=1;}Some(DistinguishingWord{left,right,word,left_answer:observe(p,pair.0),right_answer:observe(p,pair.1)})}
fn words(inputs:usize,depth:usize)->Vec<Vec<usize>>{let mut all=vec![Vec::new()];let mut level=vec![Vec::new()];for _ in 0..depth{let mut next=Vec::new();for w in &level{for a in 0..inputs{let mut w=w.clone();w.push(a);next.push(w);}}all.extend(next.clone());level=next;}all}
#[test]fn all_two_state_partial_machines_distances_budgets_and_quotients(){
 let mut cases=0;let ws=words(2,4);for labels in 0usize..4{for table in 0usize..81{let reports:Vec<_>=(0..2).map(|s|if labels&(1<<s)==0{0}else{usize::MAX}).collect();let mut n=table;let mut transitions=vec![vec![None;2];2];for r in &mut transitions{for cell in r{let v=n%3;n/=3;*cell=if v==2{None}else{Some(v)};}}
  let p=PartialDynamics::new(reports.clone(),transitions.clone(),2).unwrap();assert_eq!(p.reports(),reports);assert_eq!(p.transitions(),transitions);let d=distances(&p);
  for l in 0..2{for w in &ws{assert_eq!(p.run(l,w),Ok(partial_run(&p,l,w)));}for r in 0..2{let expected=expected_word(&p,l,r,&d);assert_eq!(p.distinguish(l,r,9),Ok(expected.clone()));for budget in 0..=9{assert_eq!(p.distinguish(l,r,budget),p.original_distinguish(l,r,budget));}if let Some(c)=expected{assert_eq!(p.verify_distinction(&c),Ok(()));let mut bad=c.clone();bad.left_answer=if bad.left_answer.is_none(){Some(0)}else{None};assert_eq!(p.verify_distinction(&bad),Err(ContinuationError::CertificateMismatch));let mut bad=c.clone();bad.right_answer=if bad.right_answer.is_none(){Some(0)}else{None};assert_eq!(p.verify_distinction(&bad),Err(ContinuationError::CertificateMismatch));let mut bad=c;bad.word.push(2);assert_eq!(p.verify_distinction(&bad),Err(ContinuationError::OutsideAlphabet));}cases+=1;}}
  let q=p.quotient();assert!(p.verify_quotient(&q));let mut expected:Vec<usize>=Vec::new();let mut roots:Vec<usize>=Vec::new();for s in 0usize..3{let class=roots.iter().position(|&r|d[s*3+r].is_none()).unwrap_or_else(||{roots.push(s);roots.len()-1});expected.push(class);}assert_eq!(q.state_to_block,expected);let dead=expected[2];assert_eq!(dead,roots.len()-1);let operations=p.quotient_operations();assert_eq!(operations.len(),dead);for a in 0..2{assert_eq!(q.quotient.transitions()[dead][a],dead);}for (class,&root) in roots[..dead].iter().enumerate(){for a in 0..2{assert_eq!(operations[class][a],p.transitions[root][a].map(|s|expected[s]));}}
  let mut bad=q.clone();bad.state_to_block[0]=usize::MAX;assert!(!p.verify_quotient(&bad));let mut bad=q;bad.partitions.clear();assert!(!p.verify_quotient(&bad));
 }}assert_eq!(cases,1296);
}
#[test]fn admission_boundaries_full_word_and_replay_scope(){
 assert_eq!(PartialDynamics::new(Vec::new(),vec![vec![Some(99)]],1),Err(ContinuationError::Machine(MooreError::EmptyCarrier)));
 assert_eq!(PartialDynamics::new(vec![0,1],vec![vec![Some(99)]],1),Err(ContinuationError::Machine(MooreError::TransitionShape)));
 assert_eq!(PartialDynamics::new(vec![0],vec![vec![Some(99),None]],1),Err(ContinuationError::Machine(MooreError::TransitionShape)));
 assert_eq!(PartialDynamics::new(vec![0],vec![vec![Some(1)]],1),Err(ContinuationError::Machine(MooreError::TransitionOutsideCarrier)));
 let p=PartialDynamics::new(vec![usize::MAX],vec![vec![None]],1).unwrap();assert_eq!(p.run(0,&[0]),Ok(None));assert_eq!(p.run(0,&[0,1]),Err(ContinuationError::OutsideAlphabet));assert_eq!(p.run(1,&[1]),Err(ContinuationError::OutsideCarrier));assert_eq!(p.distinguish(1,0,0),Err(ContinuationError::OutsideCarrier));assert_eq!(p.distinguish(0,1,0),Err(ContinuationError::OutsideCarrier));assert_eq!(p.distinguish(0,0,0),Err(ContinuationError::WorkLimit));
 let p=PartialDynamics::new(vec![0,1],vec![vec![Some(0)],vec![Some(1)]],1).unwrap();assert_eq!(p.distinguish(0,1,1).unwrap().unwrap().word,Vec::<usize>::new());let c=DistinguishingWord{left:0,right:1,word:vec![0,0,0],left_answer:Some(0),right_answer:Some(1)};assert_eq!(p.verify_distinction(&c),Ok(()),"replay does not require shortest word");let c=DistinguishingWord{left:0,right:0,word:vec![],left_answer:Some(0),right_answer:Some(0)};assert_eq!(p.verify_distinction(&c),Err(ContinuationError::CertificateMismatch));
 let p=PartialDynamics::new(vec![0,0,0,0,1],vec![vec![Some(0),Some(2)],vec![Some(1),Some(3)],vec![Some(4),Some(2)],vec![Some(3),Some(3)],vec![Some(4),Some(4)]],2).unwrap();assert_eq!(p.distinguish(0,1,25).unwrap().unwrap().word,vec![1,0]);
 for reports in [vec![usize::MAX],vec![0,0],vec![usize::MAX,0]]{let p=PartialDynamics::new(reports.clone(),vec![Vec::new();reports.len()],0).unwrap();for l in 0..reports.len(){for r in 0..reports.len(){assert_eq!(p.distinguish(l,r,1),Ok(if reports[l]==reports[r]{None}else{Some(DistinguishingWord{left:l,right:r,word:Vec::new(),left_answer:Some(reports[l]),right_answer:Some(reports[r])})}));}}assert!(p.quotient_operations().iter().all(Vec::is_empty));}
}
#[test]fn deep_first_discovery_chain_uses_predecessors(){
 let n=10000;let mut reports=vec![0;n];reports[n-1]=1;let transitions=(0..n).map(|s|vec![Some((s+1).min(n-1))]).collect();let p=PartialDynamics::new(reports,transitions,1).unwrap();let c=p.distinguish(0,1,n).unwrap().unwrap();assert_eq!(c.word,vec![0;n-2]);assert_eq!((c.left_answer,c.right_answer),(Some(0),Some(1)));assert_eq!(p.verify_distinction(&c),Ok(()));assert_eq!(p.distinguish(0,1,n-2),Err(ContinuationError::WorkLimit));
}
'''


def challenge(subject):
    return '\n#[cfg(test)]mod independent_continuation_tests{use super::*;\n'+ORIGINAL+TESTS+'\n}\n'
